function validateManifest(manifest) {
  if (manifest === null || typeof manifest !== 'object' || Array.isArray(manifest)) throw Error('manifest must be a non-array object');
  if (manifest.version !== 1) throw Error('manifest version must be exactly 1');
  if (!Array.isArray(manifest.files)) throw Error('manifest files must be an array');
  const seen = new Set();
  for (const entry of manifest.files) {
    if (entry === null || typeof entry !== 'object' || Array.isArray(entry)) throw Error('manifest entry must be a non-array object');
    validatePath(entry.path);
    if (seen.has(entry.path)) throw Error('duplicate manifest entry path');
    seen.add(entry.path);
    if (typeof entry.sha256 !== 'string' || !/^[0-9a-f]{64}$/.test(entry.sha256)) throw Error('manifest sha256 must be 64 lowercase hex characters');
    if (!Number.isSafeInteger(entry.size) || entry.size < 0) throw Error('manifest size must be a nonnegative safe integer');
    if (!Number.isInteger(entry.mode) || entry.mode < 0 || entry.mode > 511) throw Error('manifest mode must be an integer between 0 and 511');
  }
}
function stringOrder(a, b) { return a < b ? -1 : a > b ? 1 : 0; }
export function verifyManifest(root, manifest) {
  validateManifest(manifest);
  validateRoot(root);
  const unchanged = []; const changed = []; const missing = []; const unsafe = [];
  for (const entry of manifest.files) {
    const state = inspect(root, entry.path);
    if (state.kind === 'missing') { missing.push(entry.path); continue; }
    if (state.kind === 'unsafe') { unsafe.push(entry.path); continue; }
    const reasons = [];
    if (state.sha256 !== entry.sha256 || state.size !== entry.size) reasons.push('content');
    if (state.mode !== entry.mode) reasons.push('mode');
    if (reasons.length > 0) changed.push({ path: entry.path, reasons }); else unchanged.push(entry.path);
  }
  changed.sort((a, b) => stringOrder(a.path, b.path));
  unchanged.sort(stringOrder);
  missing.sort(stringOrder);
  unsafe.sort(stringOrder);
  const ok = changed.length === 0 && missing.length === 0 && unsafe.length === 0;
  return { ok, unchanged, changed, missing, unsafe };
}
function isCliEntry() {
  const entry = process.argv[1];
  if (!entry) return false;
  try { return fs.realpathSync(entry) === fs.realpathSync(fileURLToPath(import.meta.url)); }
  catch { return false; }
}
function runCli() {
  const args = process.argv.slice(2);
  try {
    if (args.length === 0) throw Error('usage: snapshot.js create ROOT [PATH ...] | snapshot.js verify ROOT MANIFEST_FILE');
    const command = args[0];
    if (command === 'create') {
      if (args.length < 2) throw Error('create requires a ROOT argument');
      const manifest = createManifest(args[1], args.slice(2));
      process.stdout.write(`${JSON.stringify(manifest)}\n`);
    } else if (command === 'verify') {
      if (args.length !== 3) throw Error('verify requires ROOT and MANIFEST_FILE arguments');
      let raw;
      try { raw = fs.readFileSync(args[2], 'utf8'); }
      catch (error) { throw Error(`cannot read manifest file: ${error.message}`); }
      let manifest;
      try { manifest = JSON.parse(raw); }
      catch (error) { throw Error(`manifest file is not valid JSON: ${error.message}`); }
      const report = verifyManifest(args[1], manifest);
      process.stdout.write(`${JSON.stringify(report)}\n`);
      if (!report.ok) process.exitCode = 1;
    } else {
      throw Error(`unknown command: ${command}`);
    }
  } catch (error) {
    const message = error && typeof error === 'object' && typeof error.message === 'string' && error.message ? error.message : String(error);
    process.stderr.write(`${message}\n`);
    process.exitCode = 2;
  }
}
if (isCliEntry()) runCli();

