  fs.mkdirSync(path.join(root, 'sub'));
  fs.writeFileSync(path.join(root, 'sub', 'b c.txt'), 'xy'); fs.chmodSync(path.join(root, 'sub', 'b c.txt'), 0o600);
  const expected = { version: 1, files: [
    { path: 'a.txt', sha256: sha('abc'), size: 3, mode: 0o640 },
