test('CLI verify exits 0 for ok, 1 for drift, 2 for errors', t => {
  const root = makeRoot(t);
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc'); fs.chmodSync(path.join(root, 'a.txt'), 0o644);
  const manifestFile = path.join(os.tmpdir(), `snapshot-cli-manifest-${process.pid}-${Math.random().toString(16).slice(2)}.json`);
  t.after(() => fs.rmSync(manifestFile, { force: true }));

  fs.writeFileSync(manifestFile, JSON.stringify({ version: 1, files: [{ path: 'a.txt', sha256: sha('abc'), size: 3, mode: 0o644 }] }));
  let res = cli(['verify', root, manifestFile]);
  assert.equal(res.status, 0);
  assert.equal(res.stderr, '');
  assert.deepEqual(JSON.parse(res.stdout), { ok: true, unchanged: ['a.txt'], changed: [], missing: [], unsafe: [] });
  assert.equal(res.stdout, JSON.stringify({ ok: true, unchanged: ['a.txt'], changed: [], missing: [], unsafe: [] }) + '\n');

  fs.chmodSync(path.join(root, 'a.txt'), 0o600);
  res = cli(['verify', root, manifestFile]);
  assert.equal(res.status, 1);
  assert.equal(res.stderr, '');
  assert.deepEqual(JSON.parse(res.stdout), { ok: false, unchanged: [], changed: [{ path: 'a.txt', reasons: ['mode'] }], missing: [], unsafe: [] });

  fs.writeFileSync(manifestFile, JSON.stringify({ version: 2, files: [] }));
  res = cli(['verify', root, manifestFile]);
  assert.equal(res.status, 2);
  assert.equal(res.stdout, '');
  assert.ok(res.stderr.length > 0);

  fs.writeFileSync(manifestFile, '{ not json');
  res = cli(['verify', root, manifestFile]);
  assert.equal(res.status, 2);
  assert.equal(res.stdout, '');
  assert.ok(res.stderr.length > 0);

  res = cli(['verify', root, path.join(root, 'no-such-manifest.json')]);
  assert.equal(res.status, 2);
  assert.equal(res.stdout, '');
  assert.ok(res.stderr.length > 0);
});

