import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import * as snapshot from '../snapshot.js';

const script = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'snapshot.js');
const sha = s => crypto.createHash('sha256').update(s, 'utf8').digest('hex');
const jsOrder = (a, b) => (a < b ? -1 : a > b ? 1 : 0);

function makeRoot(t) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-verify-'));
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  return dir;
}

function cli(args) {
  const result = spawnSync(process.execPath, [script, ...args], { encoding: 'utf8' });
  assert.equal(result.error, undefined);
  return result;
}

test('verifyManifest classifies every entry exactly once and sorts by JS string order', t => {
  const root = makeRoot(t);
  fs.writeFileSync(path.join(root, '1.txt'), 'one'); fs.chmodSync(path.join(root, '1.txt'), 0o644);
  fs.writeFileSync(path.join(root, 'A.txt'), 'alpha'); fs.chmodSync(path.join(root, 'A.txt'), 0o600);
  fs.writeFileSync(path.join(root, 'b.txt'), 'beta'); fs.chmodSync(path.join(root, 'b.txt'), 0o644);
  fs.writeFileSync(path.join(root, 'empty.bin'), ''); fs.chmodSync(path.join(root, 'empty.bin'), 0o644);
  fs.mkdirSync(path.join(root, 'sub'));
  fs.writeFileSync(path.join(root, 'sub', 'c.txt'), 'dee'); fs.chmodSync(path.join(root, 'sub', 'c.txt'), 0o644);
  fs.writeFileSync(path.join(root, 'gone.txt'), 'bye');
  fs.mkdirSync(path.join(root, 'adir'));
  fs.writeFileSync(path.join(root, 'flat.txt'), 'f');
  fs.symlinkSync('b.txt', path.join(root, 'link.txt'));
  fs.symlinkSync('sub', path.join(root, 'linkdir'));

  const manifest = { version: 1, files: [
    { path: 'b.txt', sha256: sha('beta'), size: 4, mode: 0o644 },
    { path: 'link.txt', sha256: sha('beta'), size: 4, mode: 0o644 },
    { path: 'sub/c.txt', sha256: sha('dee'), size: 3, mode: 0o644 },
    { path: 'A.txt', sha256: sha('alpha'), size: 5, mode: 0o600 },
    { path: 'adir', sha256: sha('x'), size: 1, mode: 0o755 },
    { path: 'gone.txt', sha256: sha('bye'), size: 3, mode: 0o644 },
    { path: 'nosub/c.txt', sha256: sha('dee'), size: 3, mode: 0o644 },
    { path: 'linkdir/c.txt', sha256: sha('dee'), size: 3, mode: 0o644 },
    { path: 'flat.txt/x.txt', sha256: sha('x'), size: 1, mode: 0o644 },
    { path: '1.txt', sha256: sha('one'), size: 3, mode: 0o644 },
    { path: 'empty.bin', sha256: sha(''), size: 0, mode: 0o644 },
  ]};

  fs.writeFileSync(path.join(root, 'A.txt'), 'aaaaa'); // same size, different bytes -> content
  fs.chmodSync(path.join(root, 'b.txt'), 0o640); // same bytes, different bits -> mode
  fs.writeFileSync(path.join(root, 'sub', 'c.txt'), 'deep'); // different bytes and size -> content
  fs.chmodSync(path.join(root, 'sub', 'c.txt'), 0o600); // and bits -> content + mode
  fs.unlinkSync(path.join(root, 'gone.txt'));

  assert.deepEqual(snapshot.verifyManifest(root, manifest), {
    ok: false,
    unchanged: ['1.txt', 'empty.bin'],
    changed: [
      { path: 'A.txt', reasons: ['content'] },
      { path: 'b.txt', reasons: ['mode'] },
      { path: 'sub/c.txt', reasons: ['content', 'mode'] },
    ],
    missing: ['gone.txt', 'nosub/c.txt'],
    unsafe: ['adir', 'flat.txt/x.txt', 'link.txt', 'linkdir/c.txt'],
  });
});

test('verifyManifest ignores unknown fields, accepts unsorted and empty manifests', t => {
  const root = makeRoot(t);
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc'); fs.chmodSync(path.join(root, 'a.txt'), 0o640);
  const manifest = { version: 1, files: [
