test('neither API mutates its inputs', t => {
  const root = makeRoot(t);
  fs.writeFileSync(path.join(root, 'b.txt'), 'beta'); fs.chmodSync(path.join(root, 'b.txt'), 0o644);
  fs.writeFileSync(path.join(root, 'a.txt'), 'alpha'); fs.chmodSync(path.join(root, 'a.txt'), 0o600);
  const paths = ['b.txt', 'a.txt'];
  const pathsBefore = JSON.stringify(paths);
  const manifest = { version: 1, files: [
    { path: 'b.txt', sha256: sha('beta'), size: 4, mode: 0o644 },
    { path: 'a.txt', sha256: sha('alpha'), size: 5, mode: 0o600 },
  ]};
  const manifestBefore = JSON.stringify(manifest);
  const created = snapshot.createManifest(root, paths);
  assert.equal(JSON.stringify(paths), pathsBefore);
  assert.deepEqual(created.files.map(f => f.path), ['a.txt', 'b.txt']);
  const report = snapshot.verifyManifest(root, manifest);
  assert.equal(JSON.stringify(manifest), manifestBefore);
  assert.deepEqual(report, { ok: true, unchanged: ['a.txt', 'b.txt'], changed: [], missing: [], unsafe: [] });
});

test('createManifest still throws for missing, unsafe and duplicate selections', t => {
  const root = makeRoot(t);
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc');
  fs.mkdirSync(path.join(root, 'dir'));
  assert.throws(() => snapshot.createManifest(root, ['nope.txt']), Error);
  assert.throws(() => snapshot.createManifest(root, ['dir']), Error);
  assert.throws(() => snapshot.createManifest(root, ['a.txt', 'a.txt']), Error);
  assert.throws(() => snapshot.createManifest(root, null), Error);
  assert.deepEqual(snapshot.createManifest(root, []), { version: 1, files: [] });
});

test('Unicode, space, tab and newline filenames round-trip through create and verify', t => {
  const root = makeRoot(t);
  const names = ['ünïcodé.txt', 'di r x.txt', 'ta\tb.txt', 'li\nne.txt'];
  for (const name of names) {
    fs.writeFileSync(path.join(root, name), `content of ${name}`);
    fs.chmodSync(path.join(root, name), 0o640);
  }
  const manifest = snapshot.createManifest(root, names);
  assert.equal(manifest.files.length, 4);
  const report = snapshot.verifyManifest(root, manifest);
  assert.equal(report.ok, true);
  assert.deepEqual(report.unchanged, [...names].sort(jsOrder));
});

test('CLI create prints the manifest JSON and exits 0', t => {
  const root = makeRoot(t);
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc'); fs.chmodSync(path.join(root, 'a.txt'), 0o640);
  fs.mkdirSync(path.join(root, 'sub'));
  fs.writeFileSync(path.join(root, 'sub', 'b c.txt'), 'xy'); fs.chmodSync(path.join(root, 'sub', 'b c.txt'), 0o600);
  const expected = { version: 1, files: [
    { path: 'a.txt', sha256: sha('abc'), size: 3, mode: 0o640 },
    { path: 'sub/b c.txt', sha256: sha('xy'), size: 2, mode: 0o600 },
  ]};
  const res = cli(['create', root, 'sub/b c.txt', 'a.txt']);
  assert.equal(res.status, 0);
  assert.equal(res.stderr, '');
  assert.equal(res.stdout, JSON.stringify(expected) + '\n');
  const none = cli(['create', root]);
  assert.equal(none.status, 0);
  assert.equal(none.stdout, JSON.stringify({ version: 1, files: [] }) + '\n');
  assert.equal(none.stderr, '');
});

test('CLI verify exits 0 for ok, 1 for drift, 2 for errors', t => {
  const root = makeRoot(t);
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc'); fs.chmodSync(path.join(root, 'a.txt'), 0o644);
  const manifestFile = path.join(os.tmpdir(), `snapshot-cli-manifest-${process.pid}-${Math.random().toString(16).slice(2)}.json`);
  t.after(() => fs.rmSync(manifestFile, { force: true }));

  fs.writeFileSync(manifestFile, JSON.stringify({ version: 1, files: [{ path: 'a.txt', sha256: sha('abc'), size: 3, mode: 0o644 }] }));
  let res = cli(['verify', root, manifestFile]);
  assert.equal(res.status, 0);
  assert.equal(res.stderr, '');
  assert.deepEqual(JSON.parse(res.stdout), { ok: true, unchanged: ['a.txt'], changed: [], missing: [], unsafe: [] });
  assert.equal(res.stdout, JSON.stringify({ ok: true, unchanged: ['a.txt'], changed: [], missing: [], unsafe: [] }) + '\n');

  fs.chmodSync(path.join(root, 'a.txt'), 0o600);
  res = cli(['verify', root, manifestFile]);
  assert.equal(res.status, 1);
  assert.equal(res.stderr, '');
  assert.deepEqual(JSON.parse(res.stdout), { ok: false, unchanged: [], changed: [{ path: 'a.txt', reasons: ['mode'] }], missing: [], unsafe: [] });

  fs.writeFileSync(manifestFile, JSON.stringify({ version: 2, files: [] }));
  res = cli(['verify', root, manifestFile]);
  assert.equal(res.status, 2);
  assert.equal(res.stdout, '');
  assert.ok(res.stderr.length > 0);

  fs.writeFileSync(manifestFile, '{ not json');
  res = cli(['verify', root, manifestFile]);
  assert.equal(res.status, 2);
  assert.equal(res.stdout, '');
  assert.ok(res.stderr.length > 0);

  res = cli(['verify', root, path.join(root, 'no-such-manifest.json')]);
  assert.equal(res.status, 2);
  assert.equal(res.stdout, '');
  assert.ok(res.stderr.length > 0);
});

test('CLI rejects invalid arguments, roots and selections with exit 2 and empty stdout', t => {
  const root = makeRoot(t);
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc');
  const cases = [
    [],
    ['frobnicate', root],
    ['create'],
    ['create', path.join(root, 'a.txt')],
    ['create', path.join(root, 'nope')],
    ['create', root, '../outside'],
    ['create', root, 'a.txt', 'a.txt'],
    ['verify', root],
    ['verify', root, 'x', 'y'],
    ['verify', path.join(root, 'a.txt'), 'm.json'],
  ];
  for (const args of cases) {
    const res = cli(args);
    assert.equal(res.status, 2, `args ${JSON.stringify(args)}`);
    assert.equal(res.stdout, '', `args ${JSON.stringify(args)}`);
    assert.ok(res.stderr.length > 0, `args ${JSON.stringify(args)}`);
  }
});

test('importing the module as a dependency runs no CLI', () => {
  const code = `import * as s from ${JSON.stringify(script)}; console.log(typeof s.createManifest + ' ' + typeof s.verifyManifest);`;
  const res = spawnSync(process.execPath, ['--input-type=module', '-e', code], { encoding: 'utf8' });
  assert.equal(res.error, undefined);
  assert.equal(res.status, 0);
  assert.equal(res.stdout, 'function function\n');
  assert.equal(res.stderr, '');
});

