+  res = cli(['verify', root, path.join(root, 'no-such-manifest.json')]);
+  assert.equal(res.status, 2);
+  assert.equal(res.stdout, '');
+  assert.ok(res.stderr.length > 0);
+});
+
+test('CLI rejects invalid arguments, roots and selections with exit 2 and empty stdout', t => {
+  const root = makeRoot(t);
+  fs.writeFileSync(path.join(root, 'a.txt'), 'abc');
+  const cases = [
+    [],
+    ['frobnicate', root],
+    ['create'],
+    ['create', path.join(root, 'a.txt')],
+    ['create', path.join(root, 'nope')],
+    ['create', root, '../outside'],
+    ['create', root, 'a.txt', 'a.txt'],
+    ['verify', root],
+    ['verify', root, 'x', 'y'],
+    ['verify', path.join(root, 'a.txt'), 'm.json'],
+  ];
+  for (const args of cases) {
+    const res = cli(args);
+    assert.equal(res.status, 2, `args ${JSON.stringify(args)}`);
+    assert.equal(res.stdout, '', `args ${JSON.stringify(args)}`);
+    assert.ok(res.stderr.length > 0, `args ${JSON.stringify(args)}`);
+  }
+});
+
+test('importing the module as a dependency runs no CLI', () => {
+  const code = `import * as s from ${JSON.stringify(script)}; console.log(typeof s.createManifest + ' ' + typeof s.verifyManifest);`;
+  const res = spawnSync(process.execPath, ['--input-type=module', '-e', code], { encoding: 'utf8' });
+  assert.equal(res.error, undefined);
+  assert.equal(res.status, 0);
+  assert.equal(res.stdout, 'function function\n');
+  assert.equal(res.stderr, '');
+});

